typia/package.json:
{
  "name": "typia",
  "version": "15.1.0",
  "description": "Superfast runtime validators with only one line",
  "main": "lib/index.js",
  "exports": {
    ".": "./lib/index.js",
    "./lib/module": "./lib/index.js",
    "./lib/transform": "./lib/transform.js",
    "./lib/internal/*": "./lib/internal/*.js",
    "./package.json": "./package.json"
  },
  "ttsc": {
    "plugin": {
      "transform": "typia/lib/transform"
    }
  },
  "scripts": {
    "build": "rimraf lib && ttsc && rolldown -c && node -e \"require('node:fs').copyFileSync('../../README.md', 'README.md')\"",
    "dev": "ttsc --watch",
    "evidence": "evidence"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/samchon/typia"
  },
  "author": "Jeongho Nam",
  "license": "MIT",
  "bugs": {
    "url": "https://github.com/samchon/typia/issues"
  },
  "homepage": "https://typia.io",
  "dependencies": {
    "@typia/interface": "workspace:^",
    "@typia/utils": "workspace:^",
    "randexp": "^0.5.3"
  },
  "peerDependencies": {
    "ttsc": ">=0.19.2"
  },
  "peerDependenciesMeta": {
    "ttsc": {
      "optional": true
    }
  },
  "devDependencies": {
    "@types/node": "catalog:utils",
    "rimraf": "catalog:utils",
    "rolldown": "catalog:rolldown",
    "ttsc": "catalog:samchon",
    "typescript": "catalog:typescript"
  },
  "sideEffects": false,
  "files": [
    "README.md",
    "package.json",
    "lib",
    "native",
    "src"
  ],
  "keywords": [
    "fast",
    "json",
    "stringify",
    "transform",
    "ajv",
    "io-ts",
    "zod",
    "schema",
    "json-schema",
    "generator",
    "assert",
    "clone",
    "is",
    "validate",
    "equal",
    "runtime",
    "type",
    "typebox",
    "checker",
    "validator",
    "safe",
    "parse",
    "prune",
    "random",
    "protobuf",
    "llm",
    "llm-function-calling",
    "structured-output",
    "openai",
    "chatgpt",
    "claude",
    "gemini",
    "llama"
  ],
  "packageManager": "pnpm@10.6.4",
  "publishConfig": {
    "access": "public",
    "types": "lib/index.d.ts",
    "main": "lib/index.js",
    "module": "lib/index.mjs",
    "exports": {
      ".": {
        "types": "./lib/index.d.ts",
        "import": "./lib/index.mjs",
        "default": "./lib/index.js"
      },
      "./lib/module": {
        "types": "./lib/index.d.ts",
        "import": "./lib/index.mjs",
        "default": "./lib/index.js"
      },
      "./lib/transform": {
        "types": "./lib/transform.d.ts",
        "import": "./lib/transform.mjs",
        "default": "./lib/transform.js"
      },
      "./lib/internal/*": {
        "types": "./lib/internal/*.d.ts",
        "import": "./lib/internal/*.mjs",
        "default": "./lib/internal/*.js"
      },
      "./package.json": "./package.json"
    }
  }
}

